package main

import (
	"fmt"
	"strings"
)

// Scale is the fixed-point scale for amounts: values are stored in millionths
// of a unit, so 42.50 USD is 42500000.
const Scale = 1000000

// Amount is a quantity of one currency. Currencies are never converted.
type Amount struct {
	Value    int64
	Currency string
}

// Posting is one account line of a transaction. Amounts holds more than one
// entry only for an elided posting that balances several currencies at once.
type Posting struct {
	Account string
	Amounts []Amount
	Elided  bool
	Line    int
}

// Transaction is a date line plus its postings.
type Transaction struct {
	Date     string
	Payee    string
	Postings []Posting
	Line     int
	File     string
}

// Journal is everything parsed from one file and its includes.
type Journal struct {
	Transactions []Transaction
	// Precision records the decimal places seen per currency, so output keeps
	// the precision the input used.
	Precision map[string]int
}

// ParseString parses journal text. name is used in error messages only.
func ParseString(src, name string) (*Journal, error) {
	j := &Journal{Precision: map[string]int{}}
	if err := j.parse(src, name); err != nil {
		return nil, err
	}
	return j, nil
}

func (j *Journal) parse(src, name string) error {
	lines := strings.Split(src, "\n")
	var cur *Transaction
	for i, raw := range lines {
		lineNo := i + 1
		line := stripComment(raw)
		if strings.TrimSpace(line) == "" {
			cur = nil
			continue
		}
		indented := line[0] == ' ' || line[0] == '\t'
		text := strings.TrimSpace(line)
		if !indented {
			date, payee, err := parseDateLine(text)
			if err != nil {
				return posErr(name, lineNo, err)
			}
			j.Transactions = append(j.Transactions, Transaction{
				Date: date, Payee: payee, Line: lineNo, File: name,
			})
			cur = &j.Transactions[len(j.Transactions)-1]
			continue
		}
		if cur == nil {
			return posErr(name, lineNo, fmt.Errorf("posting outside of a transaction"))
		}
		p, err := j.parsePosting(text, lineNo)
		if err != nil {
			return posErr(name, lineNo, err)
		}
		cur.Postings = append(cur.Postings, p)
	}
	return nil
}

func posErr(file string, line int, err error) error {
	return fmt.Errorf("%s:%d: %w", file, line, err)
}

func stripComment(line string) string {
	if i := strings.IndexByte(line, ';'); i >= 0 {
		return line[:i]
	}
	return line
}

func parseDateLine(text string) (date, payee string, err error) {
	date, rest, _ := strings.Cut(text, " ")
	if err := validDate(date); err != nil {
		return "", "", err
	}
	return date, strings.TrimSpace(rest), nil
}

func validDate(s string) error {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return fmt.Errorf("expected a date like 2026-01-04, got %q", s)
	}
	for i, c := range s {
		if i == 4 || i == 7 {
			continue
		}
		if c < '0' || c > '9' {
			return fmt.Errorf("expected a date like 2026-01-04, got %q", s)
		}
	}
	return nil
}

// parsePosting reads "account:sub  -42.50 USD". Two or more spaces (or a tab)
// separate the account from the amount; a posting may omit the amount entirely.
func (j *Journal) parsePosting(text string, lineNo int) (Posting, error) {
	account, amountText := splitPosting(text)
	if account == "" {
		return Posting{}, fmt.Errorf("posting has no account name")
	}
	p := Posting{Account: account, Line: lineNo}
	if amountText == "" {
		p.Elided = true
		return p, nil
	}
	amt, prec, err := parseAmount(amountText)
	if err != nil {
		return Posting{}, err
	}
	if prec > j.Precision[amt.Currency] {
		j.Precision[amt.Currency] = prec
	}
	p.Amounts = []Amount{amt}
	return p, nil
}

func splitPosting(text string) (account, amount string) {
	for i := 0; i+1 < len(text); i++ {
		if text[i] == '\t' || (text[i] == ' ' && text[i+1] == ' ') {
			return strings.TrimSpace(text[:i]), strings.TrimSpace(text[i:])
		}
	}
	if i := strings.IndexByte(text, '\t'); i >= 0 {
		return strings.TrimSpace(text[:i]), strings.TrimSpace(text[i:])
	}
	return strings.TrimSpace(text), ""
}

// parseAmount reads "-42.50 USD" or "-42.50USD" and returns the fixed-point
// value plus the number of decimal places written.
func parseAmount(text string) (Amount, int, error) {
	num, cur := splitNumber(text)
	if num == "" {
		return Amount{}, 0, fmt.Errorf("expected an amount, got %q", text)
	}
	if cur == "" {
		return Amount{}, 0, fmt.Errorf("amount %q has no currency", text)
	}
	v, prec, err := parseDecimal(num)
	if err != nil {
		return Amount{}, 0, fmt.Errorf("%w in %q", err, text)
	}
	return Amount{Value: v, Currency: cur}, prec, nil
}

func splitNumber(text string) (num, cur string) {
	i := 0
	for i < len(text) && (text[i] == '-' || text[i] == '+' || text[i] == '.' || text[i] == ',' || (text[i] >= '0' && text[i] <= '9')) {
		i++
	}
	return strings.TrimSpace(text[:i]), strings.TrimSpace(text[i:])
}

func parseDecimal(s string) (int64, int, error) {
	s = strings.ReplaceAll(s, ",", "")
	neg := false
	switch {
	case strings.HasPrefix(s, "-"):
		neg, s = true, s[1:]
	case strings.HasPrefix(s, "+"):
		s = s[1:]
	}
	intPart, fracPart, _ := strings.Cut(s, ".")
	if intPart == "" && fracPart == "" {
		return 0, 0, fmt.Errorf("malformed number")
	}
	digits := intPart + fracPart
	if digits == "" {
		return 0, 0, fmt.Errorf("malformed number")
	}
	var v int64
	for _, c := range digits {
		if c < '0' || c > '9' {
			return 0, 0, fmt.Errorf("malformed number")
		}
		v = v*10 + int64(c-'0')
	}
	prec := len(fracPart)
	if prec > 6 {
		return 0, 0, fmt.Errorf("more than 6 decimal places")
	}
	for i := prec; i < 6; i++ {
		v *= 10
	}
	if neg {
		v = -v
	}
	return v, prec, nil
}
