package main

import (
	"fmt"
	"sort"
	"strings"
)

// Check fills in every elided posting and returns one error per transaction
// that cannot be balanced. Syntax is already settled by the time it runs; these
// are semantic errors, and they are collected rather than returned one at a
// time so `validate` can report all of them.
func (j *Journal) Check() []error {
	var errs []error
	for i := range j.Transactions {
		if err := j.balance(&j.Transactions[i]); err != nil {
			errs = append(errs, err)
		}
	}
	return errs
}

func (j *Journal) balance(tx *Transaction) error {
	if len(tx.Postings) == 0 {
		return posErr(tx.File, tx.Line, fmt.Errorf("transaction %q has no postings", tx.Payee))
	}
	residual := map[string]int64{}
	elided := -1
	for i, p := range tx.Postings {
		if p.Elided {
			if elided >= 0 {
				return posErr(tx.File, tx.Postings[i].Line,
					fmt.Errorf("more than one posting omits its amount"))
			}
			elided = i
			continue
		}
		for _, a := range p.Amounts {
			residual[a.Currency] += a.Value
		}
	}
	if elided >= 0 {
		tx.Postings[elided].Amounts = negated(residual)
		return nil
	}
	if rest := nonZero(residual); len(rest) > 0 {
		return posErr(tx.File, tx.Line, fmt.Errorf("transaction %q does not balance: %s",
			tx.Payee, j.formatAmounts(rest)))
	}
	return nil
}

func negated(residual map[string]int64) []Amount {
	var out []Amount
	for _, cur := range sortedKeys(residual) {
		if residual[cur] != 0 {
			out = append(out, Amount{Value: -residual[cur], Currency: cur})
		}
	}
	return out
}

func nonZero(residual map[string]int64) []Amount {
	var out []Amount
	for _, cur := range sortedKeys(residual) {
		if residual[cur] != 0 {
			out = append(out, Amount{Value: residual[cur], Currency: cur})
		}
	}
	return out
}

func sortedKeys(m map[string]int64) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func (j *Journal) formatAmounts(amts []Amount) string {
	parts := make([]string, len(amts))
	for i, a := range amts {
		parts[i] = j.FormatAmount(a)
	}
	return strings.Join(parts, ", ")
}

// FormatAmount renders an amount with the precision its currency was written
// with in the journal, never fewer than two decimal places.
func (j *Journal) FormatAmount(a Amount) string {
	prec := j.Precision[a.Currency]
	if prec < 2 {
		prec = 2
	}
	return fmt.Sprintf("%s %s", formatFixed(a.Value, prec), a.Currency)
}

func formatFixed(v int64, prec int) string {
	sign := ""
	if v < 0 {
		sign, v = "-", -v
	}
	whole := v / Scale
	frac := v % Scale
	digits := fmt.Sprintf("%06d", frac)[:prec]
	if prec == 0 {
		return fmt.Sprintf("%s%d", sign, whole)
	}
	return fmt.Sprintf("%s%d.%s", sign, whole, digits)
}
