package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func write(t *testing.T, dir, name, body string) string {
	t.Helper()
	path := filepath.Join(dir, name)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
	return path
}

func TestIncludeIsRelativeToIncludingFile(t *testing.T) {
	dir := t.TempDir()
	write(t, dir, "sub/other.journal", `; a comment line
2026-01-05 Rent
  expenses:rent     900.00 USD  ; trailing comment
  assets:bank
`)
	main := write(t, dir, "main.journal", `include sub/other.journal

2026-01-04 Grocery store
  expenses:food      42.50 USD
  assets:bank
`)
	j, err := ParseFile(main)
	if err != nil {
		t.Fatalf("parse: %v", err)
	}
	if errs := j.Check(); len(errs) != 0 {
		t.Fatalf("check: %v", errs)
	}
	if len(j.Transactions) != 2 {
		t.Fatalf("got %d transactions, want 2", len(j.Transactions))
	}
	if j.Transactions[0].Payee != "Rent" {
		t.Errorf("first payee = %q, want Rent (included file comes first)", j.Transactions[0].Payee)
	}
	if !strings.HasSuffix(j.Transactions[0].File, filepath.Join("sub", "other.journal")) {
		t.Errorf("file = %q, want the included path", j.Transactions[0].File)
	}
	if got := j.Transactions[0].Postings[0].Amounts[0].Value; got != 900000000 {
		t.Errorf("amount = %d, want 900.00 USD with the comment stripped", got)
	}
}

