package main

import (
	"flag"
	"fmt"
	"io"
	"os"
)

const usage = `usage: ledger <command> <file> [options]

  validate <file>            report every imbalance with line numbers
  balance  <file> [--depth N]
                             account balances, tree-indented
  register <file> [--account NAME] [--since DATE] [--until DATE]
                             transaction list
`

func main() {
	os.Exit(Run(os.Args[1:], os.Stdout, os.Stderr))
}

// Run is main's body with its streams injected, so the commands are testable
// without a subprocess. It returns the process exit code.
func Run(args []string, stdout, stderr io.Writer) int {
	if len(args) == 0 {
		fmt.Fprint(stderr, usage)
		return 2
	}
	cmd, rest := args[0], args[1:]
	var err error
	switch cmd {
	case "validate":
		err = cmdValidate(rest, stdout)
	case "balance":
		err = cmdBalance(rest, stdout)
	case "register":
		err = cmdRegister(rest, stdout)
	case "-h", "--help", "help":
		fmt.Fprint(stdout, usage)
		return 0
	default:
		fmt.Fprintf(stderr, "ledger: unknown command %q\n\n%s", cmd, usage)
		return 2
	}
	if err != nil {
		fmt.Fprintf(stderr, "ledger: %v\n", err)
		if _, ok := err.(usageError); ok {
			fmt.Fprint(stderr, "\n"+usage)
			return 2
		}
		return 1
	}
	return 0
}

// usageError is a mistake in how the command was invoked, as opposed to a
// problem with the journal itself; it exits 2 and prints the usage text.
type usageError struct{ msg string }

func (e usageError) Error() string { return e.msg }

// parseArgs binds the command's flags and returns the single file operand.
func parseArgs(name string, args []string, bind func(*flag.FlagSet)) (string, error) {
	fs := flag.NewFlagSet(name, flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.Usage = func() {}
	bind(fs)
	if err := fs.Parse(args); err != nil {
		return "", usageError{err.Error()}
	}
	switch fs.NArg() {
	case 0:
		return "", usageError{fmt.Sprintf("%s needs a journal file", name)}
	case 1:
		return fs.Arg(0), nil
	default:
		return "", usageError{fmt.Sprintf("%s takes one journal file, got %d", name, fs.NArg())}
	}
}

// load parses a journal and balances it. Imbalances are returned separately
// from parse errors: validate reports them all, the other commands refuse to
// print numbers derived from a journal that does not add up.
func load(path string) (*Journal, []error, error) {
	j, err := ParseFile(path)
	if err != nil {
		return nil, nil, err
	}
	return j, j.Check(), nil
}

func cmdValidate(args []string, stdout io.Writer) error {
	path, err := parseArgs("validate", args, func(*flag.FlagSet) {})
	if err != nil {
		return err
	}
	j, bad, err := load(path)
	if err != nil {
		return err
	}
	if len(bad) > 0 {
		return errorList(bad)
	}
	fmt.Fprintf(stdout, "%s: %s balanced\n", path, plural(len(j.Transactions), "transaction"))
	return nil
}

// errorList joins several journal errors into one, so every imbalance is
// reported rather than only the first.
func errorList(errs []error) error {
	msg := ""
	for i, e := range errs {
		if i > 0 {
			msg += "\nledger: "
		}
		msg += e.Error()
	}
	return fmt.Errorf("%s", msg)
}

func plural(n int, word string) string {
	if n == 1 {
		return fmt.Sprintf("%d %s", n, word)
	}
	return fmt.Sprintf("%d %ss", n, word)
}
