package main

import (
	"flag"
	"fmt"
	"io"
	"sort"
	"strings"
)

func cmdBalance(args []string, stdout io.Writer) error {
	var depth int
	path, err := parseArgs("balance", args, func(fs *flag.FlagSet) {
		fs.IntVar(&depth, "depth", 0, "collapse accounts deeper than N levels")
	})
	if err != nil {
		return err
	}
	if depth < 0 {
		return usageError{"--depth cannot be negative"}
	}
	j, bad, err := load(path)
	if err != nil {
		return err
	}
	if len(bad) > 0 {
		return errorList(bad)
	}
	writeBalance(stdout, j, depth)
	return nil
}

// writeBalance prints every account with a non-zero balance, indented by depth,
// with each account's total including its subaccounts.
func writeBalance(w io.Writer, j *Journal, depth int) {
	totals := rollUp(j, depth)
	rows := balanceRows(j, totals)
	total := grandTotal(j)

	width := 1
	for _, r := range rows {
		if len(r.amount) > width {
			width = len(r.amount)
		}
	}
	for _, a := range total {
		if n := len(j.FormatAmount(a)); n > width {
			width = n
		}
	}
	for _, r := range rows {
		if r.name == "" {
			fmt.Fprintf(w, "%*s\n", width, r.amount)
			continue
		}
		fmt.Fprintf(w, "%*s  %s%s\n", width, r.amount, strings.Repeat("  ", r.depth-1), r.name)
	}
	fmt.Fprintln(w, strings.Repeat("-", width))
	if len(total) == 0 {
		fmt.Fprintf(w, "%*s\n", width, "0")
		return
	}
	for _, a := range total {
		fmt.Fprintf(w, "%*s\n", width, j.FormatAmount(a))
	}
}

// rollUp sums every posting into its account and all of that account's
// ancestors, so a parent line reports the subtree. Accounts below depth are
// folded into their depth-th ancestor instead of being reported separately.
func rollUp(j *Journal, depth int) map[string]map[string]int64 {
	totals := map[string]map[string]int64{}
	for _, tx := range j.Transactions {
		for _, p := range tx.Postings {
			parts := strings.Split(p.Account, ":")
			if depth > 0 && len(parts) > depth {
				parts = parts[:depth]
			}
			for i := range parts {
				name := strings.Join(parts[:i+1], ":")
				if totals[name] == nil {
					totals[name] = map[string]int64{}
				}
				for _, a := range p.Amounts {
					totals[name][a.Currency] += a.Value
				}
			}
		}
	}
	return totals
}

type balanceRow struct {
	amount string
	name   string // empty on the continuation line of a multi-currency account
	depth  int
}

func balanceRows(j *Journal, totals map[string]map[string]int64) []balanceRow {
	names := make([]string, 0, len(totals))
	for name := range totals {
		names = append(names, name)
	}
	sort.Strings(names)

	var rows []balanceRow
	for _, name := range names {
		amounts := nonZero(totals[name])
		if len(amounts) == 0 {
			continue
		}
		parts := strings.Split(name, ":")
		for i, a := range amounts {
			row := balanceRow{amount: j.FormatAmount(a), depth: len(parts)}
			if i == 0 {
				row.name = parts[len(parts)-1]
			}
			rows = append(rows, row)
		}
	}
	return rows
}

func grandTotal(j *Journal) []Amount {
	sum := map[string]int64{}
	for _, tx := range j.Transactions {
		for _, p := range tx.Postings {
			for _, a := range p.Amounts {
				sum[a.Currency] += a.Value
			}
		}
	}
	return nonZero(sum)
}

func cmdRegister(args []string, stdout io.Writer) error {
	var account, since, until string
	_, err := parseArgs("register", args, func(fs *flag.FlagSet) {
		fs.StringVar(&account, "account", "", "only postings whose account contains NAME")
		fs.StringVar(&since, "since", "", "only transactions on or after DATE")
		fs.StringVar(&until, "until", "", "only transactions on or before DATE")
	})
	return err
}
